begin; insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('service-audio','service-audio',false,10485760,array['audio/webm','audio/mp4','audio/ogg','audio/mpeg','audio/wav','audio/x-wav','audio/aac']) on conflict(id) do update set public=false,file_size_limit=10485760,allowed_mime_types=excluded.allowed_mime_types; create policy service_audio_owner_select on storage.objects for select to authenticated using(bucket_id='service-audio' and (storage.foldername(name))[1]=(select auth.uid())::text); create policy service_audio_owner_insert on storage.objects for insert to authenticated with check(bucket_id='service-audio' and (storage.foldername(name))[1]=(select auth.uid())::text); create policy service_audio_owner_delete on storage.objects for delete to authenticated using(bucket_id='service-audio' and (storage.foldername(name))[1]=(select auth.uid())::text); commit;
